with with_prev as (select *, lag(event_time) over (partition by session_id order by event_time, id) as prev_event_time from web_events), flagged as (select *, case when prev_event_time is null or event_time > prev_event_time + interval '60' day then 1 else 0 end as is_new_burst from with_prev), sessionized as (select id, session_id, event_time, sum(is_new_burst) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as island_id from flagged) select case when island_id >= 7 then 'PREMIUM' else 'STANDARD' end as island_id_tier, count(*) as cnt, count(*) as num_rows, avg(island_id) as avg_island_id from sessionized group by case when island_id >= 7 then 'PREMIUM' else 'STANDARD' end order by island_id_tier;
